import{_ as n,l,o as e,c as o,v as t,p,x as i,d as s,i as d,S as m}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"最优限价单放置理论","description":"","frontmatter":{"title":"最优限价单放置理论","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/optimal-limit-placement.md","filePath":"quant/optimal-limit-placement.md","lastUpdated":1789023840000}'),c={name:"quant/optimal-limit-placement.md"};function u(h,a,B,E,_,k){const r=l("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="最优限价单放置理论" tabindex="-1">最优限价单放置理论 <a class="header-anchor" href="#最优限价单放置理论" aria-label="Permalink to &quot;最优限价单放置理论&quot;">​</a></h1><div class="epigraph"><p>选了限价之后还要选格子：贴在 BBO 是买执行概率、卖队列位置；埋深一档是买被捡保护、卖非执行。最优档位是把上一课的两份风险标在 tick 栅格上。</p><footer>—— 据 Goettler, Parlour and Rajan, Equilibrium in a Dynamic Limit Order Market, Journal of Finance, 2005；对照 Foucault, Kadan and Kandel, Limit Order Book as a Market for Liquidity, Review of Financial Studies, 2005</footer></div><p><a href="/quant/adverse-selection-vs-nonexecution">逆向选择对非执行</a>给出目标函数的两项。缺口是离散网格上的<strong>放置</strong>：在哪一个 tick、多深的队列。Foucault–Kadan–Kandel（2005）把簿写成流动性市场，执行等待随价位变化；Goettler–Parlour–Rajan（2005）计算动态均衡的下单分布。本课写放置的一阶直觉与可观测含义，不重画<a href="/quant/price-grid-tick">价格栅格</a>的合法性，也不把执行算法的 Almgren 轨迹搬进来。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>连续价格下「挂在 \\(p\\)」是一维搜索。tick 把搜索收成少数整数档。贴 BBO：\\(\\pi_{\\mathrm{fill}}\\) 高，但同价位队可能很长，时间优先下你排在尾部，真实执行未必快；且被捡窗口开着。挂在次优档：队可能更短甚至空，但必须等 BBO 被吃掉或撤掉才轮到，非执行升、被捡降。隔空挂在更远处，几乎变成止损备忘录。问题是状态 \\((n_{\\mathrm{bbo}},n_{\\mathrm{next}},\\sigma,T)\\) 如何映射到档位，而不是再讨论要不要市价。</p><p>费用使问题非单调：有的场所对提供流动性返佣，贴 BBO 的净成本下降，放置整体前移。</p><h3 id="排队位置比档位标签更重要" tabindex="-1">排队位置比档位标签更重要 <a class="header-anchor" href="#排队位置比档位标签更重要" aria-label="Permalink to &quot;排队位置比档位标签更重要&quot;">​</a></h3><p>同样挂在 \\(b_1\\)，队头与队尾的 \\(\\pi_{\\mathrm{fill}}\\) 差一个到达过程。最优「放置」包括是否值得用更有攻击性的价格<strong>跳到新的队头</strong>（提高一个 tick 买位置）。这是在用价差换时间优先。Parlour 已说队尾可能不如市价；这里说队尾可能不如贵一个 tick 的新队头。</p><p><span class="marginnote">Obizhaeva–Wang 型最优执行是冲击函数上的轨迹，对象是市价切片。本课对象是被动单的格点。两者可组合：母单决定被动比例，子单再选档。不要把执行课的 \\(\\lambda\\) 轨迹抄进放置。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在离散档 \\(k=0,1,2,\\ldots\\)（0 为 BBO）上比较期望效用。\\(k=0\\) 的状态含队列长度；\\(k\\ge 1\\) 的成交需要先消耗更优档。FKK（2005）强调：提供更优价格的人缩短别人的等待，是在出售流动性，应获得价差；均衡等待时间随「性价比」调整。GPR（2005）显示均衡下单会填在若干档上，形状随波动与信息变化，而不是只堆在第一档。</p><p>经验：用随后的成交与中点移动，估计各档的实现 \\(\\pi\\) 与被捡；或看撤单后改挂的方向。Cont 等人的队列反应模型提供强度，但那是统计，不是本课的均衡放置。</p><h3 id="多单位与冰山" tabindex="-1">多单位与冰山 <a class="header-anchor" href="#多单位与冰山" aria-label="Permalink to &quot;多单位与冰山&quot;">​</a></h3><p>大单不能只选一个 \\(k\\)：可能拆到若干档，或同一档用冰山反复丧失时间优先。最优放置变成分配问题。隐藏理论课会说：展示量本身是信号，会改变别人的 \\(\\pi\\) 与被捡。本课默认完全可见的单位单。</p>',14)),(e(),p(m,null,{default:i(()=>[d(r,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20K0%5B%22%E6%8C%82%20BBO%3A%20%E9%AB%98%20%CF%80%2C%20%E9%95%BF%E9%98%9F%2C%20%E9%AB%98%E8%A2%AB%E6%8D%A1%22%5D%20--%3E%20Cmp%5B%22%E6%AF%94%E8%BE%83%E6%9C%9F%E6%9C%9B%E6%95%88%E7%94%A8%22%5D%0A%20%20K1%5B%22%E8%B4%B5%E4%B8%80%20tick%20%E6%96%B0%E9%98%9F%E5%A4%B4%22%5D%20--%3E%20Cmp%0A%20%20K2%5B%22%E6%AC%A1%E4%BC%98%E6%A1%A3%3A%20%E4%BD%8E%E8%A2%AB%E6%8D%A1%2C%20%E9%AB%98%E9%9D%9E%E6%89%A7%E8%A1%8C%22%5D%20--%3E%20Cmp%0A%20%20St%5B%22%E9%98%9F%E6%B7%B1%20%2F%20%CF%83%20%2F%20T%20%2F%20%E8%B4%B9%E7%94%A8%22%5D%20--%3E%20Cmp%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>放置是在揭示耐心。Roşu 的排序在栅格上变成：最急的被动者贴 BBO，次急的挂次优。观测到的深度形状是耐心分布与 tick 的卷积。tick 变粗，可区分的档变少，排队博弈加剧，时间优先更值钱——这是后文 tick size pilot 的微观机制，也是 Harris 对最小变动价位的老结论。</p><p>信息到来时，最优 \\(k\\) 立刻外移或改撤：近端变成被捡区。补给从远端往回填，形状出现「空洞」再愈合。宏观形状课会把愈合后的平均轮廓写成幂律一类描述；那是加总，不是单人最优。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>计算均衡对类型分布敏感，不能当交易台的档位计算器。真实还有 peg 指令自动贴档，把放置外包给交易所，见市场设计续。pro-rata 下「队尾」不再最差，放置逻辑翻转，下一课专门写。跨市场时本地最优档可能劣于另一场所的 BBO，路由先于放置。</p><p><span class="marginnote">回测里用事后成交标记「若挂在 k 会成交」，忽略你挂上会改变队列与别人策略，会系统性高估近端 \\(\\pi\\)。放置理论是均衡对象，不是历史簿上的点击模拟。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>最优放置在 BBO 队列、跳价抢队头、次优档之间比较 \\(\\pi\\) 与被捡。</li><li>时间优先让「同一档的位置」成为决策变量；费用与 tick 平移最优 \\(k\\)。</li><li>FKK 与 GPR 给出流动性市场与计算均衡两条理论路径。</li><li>出处：Foucault, Kadan and Kandel, <em>Review of Financial Studies</em>, 2005；Goettler, Parlour and Rajan, <em>Journal of Finance</em>, 2005。</li></ul>',8))])}const q=n(c,[["render",u]]);export{f as __pageData,q as default};
